let generatedRefs=[];
let state={ref:'',verses:[],selected:null,columns:[],language:'hebrew-bhsa',legend:[],inclusios:[],comments:[],activeCommentId:null,arcs:[],activeArcId:null};
/* Parallel passages (desktop): dual panes, verse alignment, cross-pane arcs */
const PARALLEL_MIN_WIDTH=1024;
let stateBundle={parallelEnabled:false,activePane:0,crossArcs:[],verseAlignPairs:null,generatedRefsByPane:[[],[]],panes:[null,null]};let versePairPick=null;
function freshPaneState(){return {ref:'',verses:[],selected:null,columns:[],language:'hebrew-bhsa',legend:[],inclusios:[],comments:[],activeCommentId:null,arcs:[],activeArcId:null};}
function ensureStateBundle(){if(!stateBundle.panes[0])stateBundle.panes[0]=freshPaneState();if(!stateBundle.panes[1])stateBundle.panes[1]=freshPaneState();if(!stateBundle.generatedRefsByPane[0])stateBundle.generatedRefsByPane[0]=[];if(!stateBundle.generatedRefsByPane[1])stateBundle.generatedRefsByPane[1]=[];}
function bindActivePane(idx){ensureStateBundle();const i=idx===1?1:0;syncStateBundle();stateBundle.activePane=i;state=stateBundle.panes[i];generatedRefs=stateBundle.generatedRefsByPane[i]||[];syncGeneratorFieldsFromActivePane();updateParallelModeUI();}
function syncGeneratorFieldsFromActivePane(){const refBox=document.getElementById('refBox');const pasteBox=document.getElementById('pasteBox');const textSource=document.getElementById('textSource');if(refBox)refBox.value=normalizePassageRangeRef(state.ref||'');if(pasteBox&&state.verses&&state.verses.length){pasteBox.value=state.verses.map(v=>v.clauses.flatMap(c=>c.words).filter(w=>!w.deleted).map(w=>w.text).join(' ')).join('\n');pasteBox.dir=state.language==='greek'?'ltr':'rtl';pasteBox.classList.remove('heb','greek');pasteBox.classList.add(state.language==='greek'?'greek':'heb');}if(textSource){const lang=state.language==='greek'?'greek':(state.language==='hebrew-bhsa'?'hebrew-bhsa':'hebrew');textSource.value=lang;if(typeof setupBooks==='function')setupBooks();}}
function syncStateBundle(){ensureStateBundle();stateBundle.generatedRefsByPane[stateBundle.activePane]=generatedRefs.slice();stateBundle.panes[stateBundle.activePane]=state;}
function isParallelActive(){return !!stateBundle.parallelEnabled&&window.matchMedia(`(min-width:${PARALLEL_MIN_WIDTH}px)`).matches;}
function paneLabel(idx){return idx===0?'Left passage':'Right passage';}
function formatPassageRangeRef(bookName,sc,sv,ec,ev){sc=+sc;sv=+sv;ec=+ec;ev=+ev;if(sc===ec&&sv===ev)return bookName+' '+sc+':'+sv;if(sc===ec)return bookName+' '+sc+':'+sv+'-'+ev;return bookName+' '+sc+':'+sv+'-'+ec+':'+ev;}
function normalizePassageRangeRef(refStr){const parsed=typeof parseBibleReference==='function'?parseBibleReference(refStr):null;if(!parsed)return String(refStr||'').trim();return formatPassageRangeRef(parsed.bookName,parsed.sc,parsed.sv,parsed.ec,parsed.ev);}
function normalizeProjectState(st){ensureStateBundle();const normPane=p=>{const pane=Object.assign(freshPaneState(),p||{});if(pane.ref)pane.ref=normalizePassageRangeRef(pane.ref);return pane;};if(st&&Array.isArray(st.panes)&&st.panes.length>=2){return {parallelEnabled:!!st.parallelEnabled,activePane:st.activePane===1?1:0,crossArcs:Array.isArray(st.crossArcs)?st.crossArcs:[],verseAlignPairs:Array.isArray(st.verseAlignPairs)?st.verseAlignPairs:null,panes:[normPane(st.panes[0]),normPane(st.panes[1])]};}const legacy=normPane(st||{});return {parallelEnabled:false,activePane:0,crossArcs:[],panes:[legacy,freshPaneState()]};}
function locOKInPane(l,pane){const p=pane!=null?pane:stateBundle.activePane;const st=stateBundle.panes[p];return !!(l&&st&&st.verses[l.v]&&st.verses[l.v].clauses[l.c]&&st.verses[l.v].clauses[l.c].words[l.w]);}
function locFromWordElWithPane(el){if(!el)return null;const loc={v:+el.dataset.v,c:+el.dataset.c,w:+el.dataset.w};if(el.dataset.pane!=null)loc.pane=+el.dataset.pane;return loc;}
function cloneLocWithPane(l){if(!l)return null;const o={v:+l.v,c:+l.c,w:+l.w};if(l.pane!=null)o.pane=+l.pane;return o;}
function verseRefKey(ref,fallbackIdx){const s=String(ref||'').trim();let m=s.match(/(\d+)\s*:\s*(\d+)/);if(m)return+m[1]*1000+(+m[2]);m=s.match(/(\d+)\s*$/);if(m)return+m[1];return fallbackIdx!=null?fallbackIdx:0;}function defaultVersePairs(){const left=stateBundle.panes[0].verses||[];const right=stateBundle.panes[1].verses||[];const n=Math.max(left.length,right.length,0);const pairs=[];for(let i=0;i<n;i++)pairs.push({leftVi:i<left.length?i:null,rightVi:i<right.length?i:null});return pairs;}function sanitizeVersePairs(pairs){const leftN=(stateBundle.panes[0].verses||[]).length;const rightN=(stateBundle.panes[1].verses||[]).length;if(!Array.isArray(pairs))return defaultVersePairs();return pairs.map(p=>({leftVi:p.leftVi!=null&&p.leftVi>=0&&p.leftVi<leftN?p.leftVi:null,rightVi:p.rightVi!=null&&p.rightVi>=0&&p.rightVi<rightN?p.rightVi:null}));}function materializeVersePairs(){if(!stateBundle.verseAlignPairs)stateBundle.verseAlignPairs=defaultVersePairs();else stateBundle.verseAlignPairs=sanitizeVersePairs(stateBundle.verseAlignPairs);return stateBundle.verseAlignPairs;}function computeVersePairs(){if(!stateBundle.verseAlignPairs)return defaultVersePairs();return sanitizeVersePairs(stateBundle.verseAlignPairs);}function autoAlignVersePairsByRef(){markUndo();ensureStateBundle();const left=stateBundle.panes[0].verses||[];const right=stateBundle.panes[1].verses||[];let li=0,ri=0;const pairs=[];while(li<left.length||ri<right.length){const lk=li<left.length?verseRefKey(left[li].ref,li):Infinity;const rk=ri<right.length?verseRefKey(right[ri].ref,ri):Infinity;if(li>=left.length){pairs.push({leftVi:null,rightVi:ri++});continue;}if(ri>=right.length){pairs.push({leftVi:li++,rightVi:null});continue;}if(lk===rk){pairs.push({leftVi:li++,rightVi:ri++});}else if(lk<rk){pairs.push({leftVi:li++,rightVi:null});}else{pairs.push({leftVi:null,rightVi:ri++});}}stateBundle.verseAlignPairs=pairs;versePairPick=null;if(autosaveReady)autoSaveProject();}function resetVersePairsToIndex(){markUndo();stateBundle.verseAlignPairs=null;versePairPick=null;if(autosaveReady)autoSaveProject();}function findVersePairRow(pane,vi){const pairs=materializeVersePairs();const key=pane===0?'leftVi':'rightVi';for(let i=0;i<pairs.length;i++)if(pairs[i][key]===vi)return i;return-1;}function pairVersesOnRow(paneA,viA,paneB,viB){const pairs=materializeVersePairs();const rowA=findVersePairRow(paneA,viA);const rowB=findVersePairRow(paneB,viB);if(rowA<0||rowB<0)return'missing';if(rowA===rowB)return'same';markUndo();const kA=paneA===0?'leftVi':'rightVi';const kB=paneB===0?'leftVi':'rightVi';pairs[rowA][kA]=viA;pairs[rowA][kB]=viB;if(pairs[rowB][kA]===viA)pairs[rowB][kA]=null;if(pairs[rowB][kB]===viB)pairs[rowB][kB]=null;if(autosaveReady)autoSaveProject();return'paired';}function skipVerseToNextRow(row,pane){markUndo();const pairs=materializeVersePairs();if(row<0||row>=pairs.length)return;const key=pane===0?'leftVi':'rightVi';const vi=pairs[row][key];if(vi==null)return;pairs[row][key]=null;pairs.splice(row+1,0,{leftVi:pane===0?vi:null,rightVi:pane===1?vi:null});if(autosaveReady)autoSaveProject();}function clearVerseAlignState(){stateBundle.verseAlignPairs=null;versePairPick=null;}function remapPaneLocAfterVerseRemoval(l,removedVi){if(!l||l.v==null)return null;if(l.v===removedVi)return null;if(l.v>removedVi)return{v:l.v-1,c:l.c,w:l.w};return{v:l.v,c:l.c,w:l.w};}function remapPaneLocAfterClauseRemoval(l,vi,removedCi){if(!l||l.v==null)return null;if(l.v!==vi)return{v:l.v,c:l.c,w:l.w};if(l.c===removedCi)return null;if(l.c>removedCi)return{v:vi,c:l.c-1,w:l.w};return{v:vi,c:l.c,w:l.w};}function remapPaneStateLocs(st,remapFn){if(Array.isArray(st.comments))st.comments=st.comments.map(cm=>{const start=remapFn(cm.start),end=remapFn(cm.end);if(!start||!end)return null;return Object.assign({},cm,{start,end});}).filter(Boolean);if(Array.isArray(st.arcs))st.arcs=st.arcs.map(arc=>{const start=remapFn(arc.start),end=remapFn(arc.end);if(!start||!end)return null;return Object.assign({},arc,{start,end});}).filter(Boolean);if(Array.isArray(st.inclusios))st.inclusios=st.inclusios.map(inc=>{const start=remapFn(inc.start),end=remapFn(inc.end);if(!start||!end)return null;return Object.assign({},inc,{start,end});}).filter(Boolean);if(st.selected){const sel=remapFn(st.selected);st.selected=sel||null;}if(st.activeCommentId&&(!st.comments||!st.comments.some(c=>c.id===st.activeCommentId)))st.activeCommentId=null;if(st.activeArcId&&(!st.arcs||!st.arcs.some(a=>a.id===st.activeArcId)))st.activeArcId=null;}function adjustVersePairsAfterVerseRemoval(pane,removedVi){const key=pane===0?'leftVi':'rightVi';const pairs=materializeVersePairs();pairs.forEach(p=>{const vi=p[key];if(vi===removedVi)p[key]=null;else if(vi!=null&&vi>removedVi)p[key]=vi-1;});stateBundle.verseAlignPairs=pairs;}function pruneCrossArcsForPane(pane){ensureCrossArcs();stateBundle.crossArcs=stateBundle.crossArcs.filter(arc=>{const sp=arc.start.pane!=null?+arc.start.pane:0;const ep=arc.end.pane!=null?+arc.end.pane:1;if(sp===pane&&!locOKInPane(arc.start,pane))return false;if(ep===pane&&!locOKInPane(arc.end,pane))return false;return true;});}function removeVerseFromPane(pane,vi,skipConfirm){ensureStateBundle();const st=stateBundle.panes[pane];if(!st||!st.verses[vi])return;const ref=st.verses[vi].ref||'this verse';if(!skipConfirm&&!confirm('Remove '+ref+' from '+paneLabel(pane)+'? Annotations on this verse will be removed.'))return;markUndo();const remap=l=>remapPaneLocAfterVerseRemoval(l,vi);remapPaneStateLocs(st,remap);st.verses.splice(vi,1);if(Array.isArray(stateBundle.generatedRefsByPane[pane]))stateBundle.generatedRefsByPane[pane].splice(vi,1);adjustVersePairsAfterVerseRemoval(pane,vi);pruneCrossArcsForPane(pane);if(versePairPick&&versePairPick.pane===pane&&versePairPick.vi===vi)versePairPick=null;else if(versePairPick&&versePairPick.pane===pane&&versePairPick.vi>vi)versePairPick.vi--;if(stateBundle.activePane===pane){state=st;if(typeof applyInclusioBrackets==='function')applyInclusioBrackets(false);}if(autosaveReady)autoSaveProject();updateSaveStatus('Removed '+ref+' from '+paneLabel(pane)+'. Reload the passage to restore it.');render();}function removeClauseFromPane(pane,v,ci){ensureStateBundle();const st=stateBundle.panes[pane];if(!st||!st.verses[v]||!st.verses[v].clauses[ci])return;const verse=st.verses[v];if(verse.clauses.length===1){removeVerseFromPane(pane,v,true);return;}markUndo();const remap=l=>remapPaneLocAfterClauseRemoval(l,v,ci);remapPaneStateLocs(st,remap);verse.clauses.splice(ci,1);pruneCrossArcsForPane(pane);if(stateBundle.activePane===pane){state=st;if(typeof applyInclusioBrackets==='function')applyInclusioBrackets(false);}if(autosaveReady)autoSaveProject();updateSaveStatus('Removed section from '+verse.ref+'.');render();}function removeClauseFromActivePane(){if(!state.selected||!locOK(state.selected))return;removeClauseFromPane(stateBundle.activePane,state.selected.v,state.selected.c);}function countLeadingRightOffset(){const pairs=materializeVersePairs();let n=0;for(let i=0;i<pairs.length;i++){if(pairs[i].leftVi!=null&&pairs[i].rightVi==null)n++;else if(pairs[i].rightVi!=null)break;}return n;}function shiftRightColumnDown(){markUndo();const pairs=materializeVersePairs();if(!pairs.length)return;const rights=pairs.map(p=>p.rightVi);for(let i=0;i<pairs.length;i++)pairs[i].rightVi=null;for(let i=0;i<rights.length;i++){if(rights[i]==null)continue;const target=i+1;while(target>=pairs.length)pairs.push({leftVi:null,rightVi:null});pairs[target].rightVi=rights[i];}if(autosaveReady)autoSaveProject();}function shiftRightColumnUp(){markUndo();if(countLeadingRightOffset()<=0)return;const pairs=materializeVersePairs();const rights=[];for(const p of pairs)if(p.rightVi!=null)rights.push(p.rightVi);for(const p of pairs)p.rightVi=null;for(let i=0;i<rights.length;i++){if(i>=pairs.length)pairs.push({leftVi:null,rightVi:null});pairs[i].rightVi=rights[i];}if(autosaveReady)autoSaveProject();}function nudgeVerseUp(row,pane){markUndo();if(row<=0)return;const pairs=materializeVersePairs();const key=pane===0?'leftVi':'rightVi';const vi=pairs[row][key];if(vi==null)return;const prev=pairs[row-1][key];pairs[row-1][key]=vi;pairs[row][key]=prev;if(autosaveReady)autoSaveProject();}function updateParallelAlignStatus(){const el=document.getElementById('parallelAlignStatus');if(!el)return;if(!stateBundle.parallelEnabled){el.textContent='';return;}if(!isParallelActive()){el.textContent='Parallel passages on — widen the window for side-by-side view.';return;}if(versePairPick){const st=stateBundle.panes[versePairPick.pane];const ref=(st.verses[versePairPick.vi]&&st.verses[versePairPick.vi].ref)||'verse';el.innerHTML='Selected <strong>'+esc(ref)+'</strong> — click the matching verse in the other column. <button type="button" class="linkish-btn" id="cancelVersePickBtn">Cancel</button>';const cancel=document.getElementById('cancelVersePickBtn');if(cancel)cancel.onclick=(e)=>{e.preventDefault();versePairPick=null;render();};return;}const off=countLeadingRightOffset();let msg=off?('Right pane starts '+off+' row'+(off===1?'':'s')+' lower than the left.'):'Right and left panes start on the same row.';msg+=' Toolbar <strong>↑</strong> / <strong>↓</strong> shift the whole right pane up or down (Alt+↑ / Alt+↓). Small <strong>↑</strong> / <strong>↓</strong> beside a verse on the right move that verse only. Click two verse labels to pair them on one row.';if(off>0)msg+=' <button type="button" class="linkish-btn" id="resetVerseAlignLink">Reset</button>';if(state.selected&&locOK(state.selected)&&stateBundle.activePane!=null)msg+=' <button type="button" class="linkish-btn" id="removeClauseSectionBtn">Remove this section</button>';el.innerHTML=msg;const reset=document.getElementById('resetVerseAlignLink');if(reset)reset.onclick=(e)=>{e.preventDefault();resetVersePairsToIndex();render();};const trimBtn=document.getElementById('removeClauseSectionBtn');if(trimBtn)trimBtn.onclick=(e)=>{e.preventDefault();removeClauseFromActivePane();};}
function paneLanguage(pane){const st=stateBundle.panes[pane];return st&&st.language?st.language:'hebrew';}
function renderVerseBlock(pane,vi,paneState,layout,activeKey,row){if(vi==null||!paneState.verses[vi])return '<div class="parallel-empty-verse muted small">—</div>';const v=paneState.verses[vi];const picked=versePairPick&&versePairPick.pane===pane&&versePairPick.vi===vi;const ri=row!=null?row:0;let html=`<div class="parallel-verse-ref-bar" dir="ltr">${pane===1?`<button type="button" class="parallel-nudge-btn" data-row="${ri}" data-gap="${pane}" data-dir="up" title="Move this verse up one row">↑</button>`:""}<span class="muted parallel-verse-ref parallel-verse-pick${picked?" parallel-verse-picked":""}" data-pane="${pane}" data-vi="${vi}" title="Click this label, then click a verse label in the other column to line them up on one row">${esc(v.ref)}</span>${pane===1?`<button type="button" class="parallel-nudge-btn" data-row="${ri}" data-gap="${pane}" title="Move this verse down one row">↓</button>`:""}<button type="button" class="parallel-verse-remove" data-pane="${pane}" data-vi="${vi}" title="Remove this verse from this pane">×</button></div>`;v.clauses.forEach((c,ci)=>{const sel=paneState.selected&&paneState.selected.v===vi&&paneState.selected.c===ci;const marginStyle=layout.indentSide==='left'?`margin-left:${c.indent*36}px`:`margin-right:${c.indent*36}px`;html+=`<div class="clause ${sel?'selected':''}" data-pane="${pane}" data-v="${vi}" data-c="${ci}" dir="${layout.dir}" style="${marginStyle};direction:${layout.dir};text-align:${layout.textAlign};font-family:${layout.fontFamily}">`;c.words.forEach((w,wi)=>{const l={v:vi,c:ci,w:wi,pane};const ids=commentIdsForLocInPane(l,pane);const commentClass=ids.length?'comment-anchored':'';const activeCommentClass=(paneState.activeCommentId&&ids.includes(paneState.activeCommentId))?'comment-active':'';const wsel=paneState.selected&&paneState.selected.v===vi&&paneState.selected.c===ci&&paneState.selected.w===wi;const same=activeKey&&normalizeHebrewWord(w.text)===activeKey&&!wsel;html+=`<span class="word ${wsel?'selected':''} ${same?'sameword':''} ${commentClass} ${activeCommentClass} ${w.deleted?'deleted':''} ${w.specials.includes('predicate')?'pred':''} ${w.specials.includes('subject')?'subj':''} ${wordFormatClasses(w,l)}" data-pane="${pane}" data-v="${vi}" data-c="${ci}" data-w="${wi}" style="${wordInlineStyle(w)}">${esc(w.text)}</span>${commentMarkersForLocInPane(l,pane)} `;});html+='</div>';});return html;}
function locRankInPane(l,pane){const st=stateBundle.panes[pane];if(!st||!locOKInPane(l,pane))return-1;let n=0;for(let vi=0;vi<st.verses.length;vi++){for(let ci=0;ci<st.verses[vi].clauses.length;ci++){if(vi===l.v&&ci===l.c)return n+l.w;n+=st.verses[vi].clauses[ci].words.length;}}return-1;}
function locInRangeInPane(l,start,end,pane){if(!locOKInPane(l,pane)||!locOKInPane(start,pane)||!locOKInPane(end,pane))return false;const r=locRankInPane(l,pane),a=locRankInPane(start,pane),b=locRankInPane(end,pane);return r>=Math.min(a,b)&&r<=Math.max(a,b);}
function commentIdsForLocInPane(l,pane){const st=stateBundle.panes[pane];if(!st||!Array.isArray(st.comments))return[];return st.comments.filter(cm=>locOKInPane(cm.start,pane)&&locOKInPane(cm.end,pane)&&locInRangeInPane(l,cm.start,cm.end,pane)).map(cm=>cm.id);}
function commentMarkersForLocInPane(l,pane){const st=stateBundle.panes[pane];if(!st||!Array.isArray(st.comments))return'';return st.comments.map((cm,idx)=>locOKInPane(cm.start,pane)&&locEqual(l,cm.start)?`<sup class="comment-marker" data-comment-id="${esc(cm.id)}">${idx+1}</sup>`:'').join('');}
function sameLocInPane(a,b,pane){return locOKInPane(a,pane)&&locOKInPane(b,pane)&&a.v===b.v&&a.c===b.c&&a.w===b.w;}
function attachParallelWordHandlers(root){root.querySelectorAll('.word').forEach(el=>{el.onclick=(ev)=>{const pane=+el.dataset.pane;bindActivePane(pane);const clicked={v:+el.dataset.v,c:+el.dataset.c,w:+el.dataset.w};if(ev.shiftKey&&locOK(state.selected)){applyBracketRange(state.selected,clicked);return;}state.selected=clicked;syncStateBundle();const mk=crossPaneMatchKey();if(mk){const wtxt=state.verses[clicked.v].clauses[clicked.c].words[clicked.w].text;updateSaveStatus('Highlighting every instance of “'+wtxt+'” in both panes.');}else updateSaveStatus('Word selected.');renderParallelEditors();};});root.querySelectorAll('.clause').forEach(el=>{el.onclick=(ev)=>{if(ev.target.classList.contains('word'))return;bindActivePane(+el.dataset.pane);state.selected={v:+el.dataset.v,c:+el.dataset.c,w:0};renderParallelEditors();};});}function attachParallelAlignHandlers(root){root.querySelectorAll('.parallel-nudge-btn').forEach(btn=>{btn.onclick=(ev)=>{ev.stopPropagation();const row=+btn.dataset.row,pane=+btn.dataset.gap;if(btn.dataset.dir==='up')nudgeVerseUp(row,pane);else skipVerseToNextRow(row,pane);render();};});root.querySelectorAll('.parallel-verse-remove').forEach(btn=>{btn.onclick=(ev)=>{ev.stopPropagation();removeVerseFromPane(+btn.dataset.pane,+btn.dataset.vi);};});root.querySelectorAll('.parallel-verse-pick').forEach(el=>{el.onclick=(ev)=>{ev.stopPropagation();const pane=+el.dataset.pane,vi=+el.dataset.vi;if(!versePairPick){versePairPick={pane,vi};const st0=stateBundle.panes[pane];const ref0=(st0.verses[vi]&&st0.verses[vi].ref)||'verse';updateSaveStatus('Selected '+ref0+' — click the matching verse label in the other column.');renderParallelEditors();return;}if(versePairPick.pane===pane){versePairPick={pane,vi};renderParallelEditors();return;}const pr=pairVersesOnRow(versePairPick.pane,versePairPick.vi,pane,vi);versePairPick=null;if(pr==='same')updateSaveStatus('Those verses are already on the same row.');else if(pr==='paired')updateSaveStatus('Verses linked on the same row.');else updateSaveStatus('Could not pair those verses.');render();};});}
function equalizeParallelRowHeights(){document.querySelectorAll('.parallel-verse-row').forEach(row=>{const cells=row.querySelectorAll('.parallel-verse-cell');let maxH=0;cells.forEach(c=>{c.style.minHeight='';maxH=Math.max(maxH,c.offsetHeight);});cells.forEach(c=>{c.style.minHeight=maxH+'px';});});}
function crossPaneMatchKey(){const ap=stateBundle.activePane;const st=stateBundle.panes[ap];if(!st||!st.selected||!locOKInPane(st.selected,ap))return '';return normalizeHebrewWord(st.verses[st.selected.v].clauses[st.selected.c].words[st.selected.w].text);}function renderParallelEditors(){ensureStateBundle();const wrap=document.getElementById('parallelCompareWrap');const single=document.getElementById('singleEditorSection');const rowsEl=document.getElementById('parallelVerseRows');if(!wrap||!rowsEl)return;if(!isParallelActive()){wrap.classList.add('hidden');if(single)single.classList.remove('hidden');return;}wrap.classList.remove('hidden');if(single)single.classList.add('hidden');const pairs=computeVersePairs();const matchKey=crossPaneMatchKey();let html='';[0,1].forEach(pane=>{const refIn=document.getElementById('parallelPaneRef'+pane);const head=document.getElementById('parallelPaneHead'+pane);const st=stateBundle.panes[pane];if(refIn){if(document.activeElement!==refIn)refIn.value=normalizePassageRangeRef(st.ref||'');refIn.classList.toggle('parallel-pane-active',stateBundle.activePane===pane);}else if(head){head.textContent=st.ref||paneLabel(pane);head.classList.toggle('parallel-pane-active',stateBundle.activePane===pane);}});pairs.forEach((pair,ri)=>{if(pair.leftVi==null&&pair.rightVi==null)return;html+=`<div class="parallel-verse-row" data-row="${ri}">`;[0,1].forEach(pane=>{const vi=pane===0?pair.leftVi:pair.rightVi;if(vi==null){html+=`<div class="parallel-verse-cell parallel-verse-cell-empty" data-pane="${pane}" data-row="${ri}" aria-hidden="true"></div>`;return;}const paneState=stateBundle.panes[pane];if(!paneState.verses[vi]){html+=`<div class="parallel-verse-cell parallel-verse-cell-empty" data-pane="${pane}" data-row="${ri}" aria-hidden="true"></div>`;return;}const layout=getLanguageLayout(paneState.language);html+=`<div class="parallel-verse-cell ${stateBundle.activePane===pane?'pane-active':''}" data-pane="${pane}" data-row="${ri}"><div class="parallel-pane-arc-wrap" data-pane="${pane}"><svg class="paneArcSvg" data-pane="${pane}" aria-hidden="true"></svg><div class="parallel-verse-body">${renderVerseBlock(pane,vi,paneState,layout,matchKey,ri)}</div></div></div>`;});html+='</div>';});if(!pairs.length)html='<div class="editor-empty-state" dir="ltr"><p class="editor-empty-title">Load a passage into each pane</p><p class="muted">Use <strong>Generate text</strong> or <strong>Paste text</strong> — the active pane is highlighted below.</p></div>';rowsEl.innerHTML=html;attachParallelWordHandlers(rowsEl);attachParallelAlignHandlers(rowsEl);bindParallelPaneRefInputs();requestAnimationFrame(()=>{equalizeParallelRowHeights();renderParallelArcOverlays();renderCrossArcOverlay();updateParallelModeUI();updateParallelAlignStatus();});}
function renderParallelArcOverlays(){[0,1].forEach(pane=>{const paneState=stateBundle.panes[pane];ensureArcsInPane(pane);const svg=document.querySelector(`.paneArcSvg[data-pane="${pane}"]`);const wrap=document.querySelector(`.parallel-pane-arc-wrap[data-pane="${pane}"]`);if(!svg||!wrap)return;svg.innerHTML='';const wr=wrap.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${Math.max(1,wr.width)} ${Math.max(1,wr.height)}`);svg.setAttribute('width',wr.width);svg.setAttribute('height',wr.height);document.querySelectorAll(`.word[data-pane="${pane}"].arc-anchor`).forEach(w=>w.classList.remove('arc-anchor'));paneState.arcs.forEach(arc=>{const a=wordElForLoc(arc.start,pane);const b=wordElForLoc(arc.end,pane);if(!a||!b)return;a.classList.add('arc-anchor');b.classList.add('arc-anchor');const geo=arcGeometryForLocsInPane(arc.start,arc.end,pane,wr);if(!geo)return;const color=arc.color||'#0b61d8';drawArcPath(svg,geo,color);drawArcLabel(svg,geo,arc,color);});if(arcDraw.active&&arcDraw.start&&arcDraw.current){const sp=arcDraw.start.pane!=null?+arcDraw.start.pane:stateBundle.activePane;const ep=arcDraw.current.pane!=null?+arcDraw.current.pane:stateBundle.activePane;if(sp===ep&&pane===sp&&!sameLocInPane(arcDraw.start,arcDraw.current,pane)){const geo=arcGeometryForLocsInPane(arcDraw.start,arcDraw.current,pane,wr);if(geo)drawArcPath(svg,geo,arcColorValue(),{preview:true});}}});}
