function renderArcManagerParallel(){const mgr=document.getElementById('arcManager');if(!mgr)return;if(!isParallelActive()){renderArcManager();return;}ensureCrossArcs();let html='<div class="small"><strong>Cross-pane arcs</strong></div>';if(!stateBundle.crossArcs.length)html+='<p class="muted small">Draw from a word in one passage to a word in the other.</p>';stateBundle.crossArcs.forEach(arc=>{html+=`<div class="arc-item ${state.activeArcId===arc.id?'active':''}" data-arc-id="${esc(arc.id)}"><span>${esc(arcLabelText(arc))}</span> <span class="muted">${esc(paneLabel(arc.start.pane))} → ${esc(paneLabel(arc.end.pane))}</span></div>`;});[0,1].forEach(pane=>{const st=stateBundle.panes[pane];if(!st.arcs||!st.arcs.length)return;html+=`<div class="small" style="margin-top:8px"><strong>${esc(paneLabel(pane))} arcs</strong></div>`;st.arcs.forEach(arc=>{html+=`<div class="arc-item ${state.activeArcId===arc.id?'active':''}" data-arc-id="${esc(arc.id)}" data-pane="${pane}"><span>${esc(arcLabelText(arc))}</span></div>`;});});mgr.innerHTML=html;mgr.querySelectorAll('.arc-item').forEach(el=>{el.onclick=()=>{if(el.dataset.pane)bindActivePane(+el.dataset.pane);state.activeArcId=el.dataset.arcId;render();};});}
