function nearestWordLocFromPointParallel(x,y){const fromPoint=(document.elementsFromPoint?document.elementsFromPoint(x,y):[]).find(el=>el.classList&&el.classList.contains('word'));if(fromPoint)return locFromWordElWithPane(fromPoint);let words=[...document.querySelectorAll('#parallelVerseRows .word')];let best=null,bestDist=Infinity;words.forEach(el=>{const r=el.getBoundingClientRect();const cx=Math.min(Math.max(x,r.left),r.right),cy=Math.min(Math.max(y,r.top),r.bottom);const d=(x-cx)*(x-cx)+(y-cy)*(y-cy);if(d<bestDist){bestDist=d;best=el;}});return bestDist<16000?locFromWordElWithPane(best):null;}
