function bindParallelPaneRefInputs(){document.querySelectorAll('.parallel-pane-ref-input').forEach(inp=>{if(inp.dataset.refBound)return;inp.dataset.refBound='1';inp.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();inp.blur();}});inp.addEventListener('blur',()=>{const val=inp.value.trim();if(val)applyPaneReferenceFromInput(+inp.dataset.pane,val);});inp.addEventListener('click',e=>{e.stopPropagation();bindActivePane(+inp.dataset.pane);});});}function parseText(text,ref,preserve){const keep=preserve!==false&&state.verses&&state.verses.length;const snap=keep?{verses:JSON.parse(JSON.stringify(state.verses)),comments:JSON.parse(JSON.stringify(state.comments||[])),arcs:JSON.parse(JSON.stringify(state.arcs||[])),inclusios:JSON.parse(JSON.stringify(state.inclusios||[])),legend:state.legend}:null;state.legend=snap?snap.legend:(state.legend||[]);if(!keep){state.inclusios=[];state.comments=[];state.arcs=[];state.activeArcId=null;state.activeCommentId=null;}state.ref=ref?normalizePassageRangeRef(ref):'';syncLanguageFromSource();const lines=text.split(/\n+/);state.verses=lines.map((line,i)=>({ref:(generatedRefs[i]|| (ref?ref+(text.includes('\n')?' line '+(i+1):''):'Line '+(i+1))),clauses:[{indent:0,words:line.trim().split(/\s+/).filter(Boolean).map(w=>({text:w,deleted:false,specials:[],note:'',translation:'',color:''})),ann:{}}]})).filter(v=>v.clauses[0].words.length);if(snap){state.verses.forEach(nv=>{const oi=findVerseIndexByRef(snap.verses,nv.ref);if(oi>=0)mergeVerseData(snap.verses[oi],nv);});state.comments=snap.comments;state.arcs=snap.arcs;state.inclusios=snap.inclusios;remapPaneAnnotations(snap.verses,state.verses,state);}state.selected=null;if(stateBundle&&stateBundle.parallelEnabled){if(!keep)clearVerseAlignState();else if(stateBundle.verseAlignPairs)stateBundle.verseAlignPairs=sanitizeVersePairs(stateBundle.verseAlignPairs);syncStateBundle();}render();}
function locOK(l,pane){if(pane!=null||(l&&l.pane!=null))return locOKInPane(l,pane!=null?pane:l.pane);return l&&state.verses[l.v]&&state.verses[l.v].clauses[l.c]&&state.verses[l.v].clauses[l.c].words[l.w];}
