function addCommentFromSelection(){markUndo();ensureComments();if(!locOK(state.selected)){alert('Select a word or phrase endpoint first.');return;}let start=commentAnchorStart&&locOK(commentAnchorStart)?cloneLoc(commentAnchorStart):cloneLoc(state.selected);let end=cloneLoc(state.selected);let ordered=orderedLocs(start,end);start=cloneLoc(ordered[0]);end=cloneLoc(ordered[1]);let anchor=commentAnchorText(start,end);promptModal('Add Comment','Comment on: '+anchor,'',txt=>{if(!String(txt||'').trim())return;let id=nextCommentId();state.comments.push({id,start,end,text:txt,createdAt:new Date().toISOString()});state.activeCommentId=id;commentAnchorStart=null;render();});}
function activateComment(id){ensureComments();state.activeCommentId=id;let cm=state.comments.find(c=>c.id===id);if(cm&&locOK(cm.start))state.selected=cloneLoc(cm.start);render();setTimeout(()=>{let w=document.querySelector(`.word[data-v="${cm?.start?.v}"][data-c="${cm?.start?.c}"][data-w="${cm?.start?.w}"]`);if(w)w.scrollIntoView({behavior:'smooth',block:'center'});},50);}
function editComment(id){ensureComments();let cm=state.comments.find(c=>c.id===id);if(!cm)return;promptModal('Edit Comment','Comment on: '+commentAnchorText(cm.start,cm.end),cm.text,txt=>{markUndo();cm.text=txt;state.activeCommentId=id;render();});}
function deleteComment(id){markUndo();ensureComments();let cm=state.comments.find(c=>c.id===id);if(!cm)return;if(confirm('Delete this comment?')){state.comments=state.comments.filter(c=>c.id!==id);if(state.activeCommentId===id)state.activeCommentId=null;render();}}
function renderCommentsPanel(){
  let panel=document.getElementById('commentsPanel');
  let wrapper=document.querySelector('.contour-with-comments');
  let showBtn=document.getElementById('showCommentsPanel');
  if(!panel)return;
  ensureComments();
  if(wrapper)wrapper.classList.toggle('comments-collapsed', !!commentsPanelCollapsed);
  if(showBtn){
    showBtn.classList.toggle('hidden', !commentsPanelCollapsed);
    showBtn.onclick=()=>{commentsPanelCollapsed=false;renderCommentsPanel();};
  }
  let collapsedClass=commentsPanelCollapsed?' collapsed':'';
  let html=`<div class="comments-panel-header"><h3>Comments</h3><button class="comments-collapse-btn" id="toggleCommentsPanel">Hide</button></div><div class="comments-panel-body"><p class="muted small">Comments are anchored to words or phrases in the Contour Editor and are excluded from Table View.</p>`;
  if(!state.comments.length){
    html+='<p class="muted">No comments yet.</p></div>';
    panel.className='comments-panel'+collapsedClass;
    panel.innerHTML=html;
    let t=document.getElementById('toggleCommentsPanel');if(t)t.onclick=()=>{commentsPanelCollapsed=true;renderCommentsPanel();};
    return;
  }
  state.comments.forEach((cm,idx)=>{
    let active=state.activeCommentId===cm.id;
    html+=`<div class="comment-card ${active?'active':''}" data-comment-id="${esc(cm.id)}"><div class="comment-anchor">[${idx+1}] ${esc(commentAnchorText(cm.start,cm.end)||'Anchor missing')}</div><div class="comment-text" dir="ltr">${esc(cm.text)}</div><div class="comment-actions"><button class="btn small" data-edit-comment="${esc(cm.id)}">Edit</button><button class="btn danger small" data-delete-comment="${esc(cm.id)}">Delete</button></div></div>`;
  });
  html+='</div>';
  panel.className='comments-panel'+collapsedClass;
  panel.innerHTML=html;
  let t=document.getElementById('toggleCommentsPanel');if(t)t.onclick=()=>{commentsPanelCollapsed=true;renderCommentsPanel();};
  panel.querySelectorAll('.comment-card').forEach(card=>card.onclick=e=>{if(e.target.tagName==='BUTTON')return;activateComment(card.dataset.commentId);});
  panel.querySelectorAll('[data-edit-comment]').forEach(btn=>btn.onclick=e=>{e.stopPropagation();editComment(btn.dataset.editComment);});
  panel.querySelectorAll('[data-delete-comment]').forEach(btn=>btn.onclick=e=>{e.stopPropagation();deleteComment(btn.dataset.deleteComment);});
}

function commentsHtmlForExport(){ensureComments();if(!state.comments.length)return '';let entries=state.comments.map((cm,idx)=>`<div class="export-comment"><div class="export-comment-anchor">[${idx+1}] ${esc(commentAnchorText(cm.start,cm.end)||'Anchor missing')}</div><div>${esc(cm.text).replace(/\n/g,'<br>')}</div></div>`).join('');return `<div class="export-comments"><h3>Comments</h3>${entries}</div>`;}

let autosaveReady=false;
